import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"اصطلاحات کا لغت","description":"","frontmatter":{},"headers":[],"relativePath":"ur/90-术语词典.md","filePath":"ur/90-术语词典.md","lastUpdated":null}'),l={name:"ur/90-术语词典.md"};function o(i,t,h,n,u,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="اصطلاحات-کا-لغت" tabindex="-1">اصطلاحات کا لغت <a class="header-anchor" href="#اصطلاحات-کا-لغت" aria-label="Permalink to &quot;اصطلاحات کا لغت&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>90</td></tr><tr><td>ماڈیول</td><td>ضمیمے اور حوالہ جات</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>اصطلاحات کا لغت، بنیادی تصورات، تعریفیں، متحد اصطلاحات، ہینگیوانژو</td></tr></tbody></table><h2 id="_1-اصطلاحات-کی-وضاحت" tabindex="-1">1. اصطلاحات کی وضاحت <a class="header-anchor" href="#_1-اصطلاحات-کی-وضاحت" aria-label="Permalink to &quot;1. اصطلاحات کی وضاحت&quot;">​</a></h2><p>یہ لغت اینکر سمبیوسس تہذیب کے ترتیب کے نظام میں بنیادی اصطلاحات پر مشتمل ہے، جس کا مقصد تمام دستاویزات میں اصطلاحات کے استعمال کو متحد کرنا اور تصورات کے اظہار کی مستقل مزاجی اور درستگی کو یقینی بنانا ہے۔ تمام اصطلاحات چینی پنین کے پہلے حرف کے لحاظ سے ترتیب دی گئی ہیں، اور ہر اصطلاح میں اصطلاح کا نام، انگریزی حوالہ نام (اگر موجود ہو)، تعریف اور مختصر وضاحت شامل ہے۔ یہ لغت ایک متحرک اپ ڈیٹ دستاویز ہے، اور ترتیب کے نظام کی توسیع کے ساتھ ساتھ نئی اصطلاحات مسلسل شامل کی جائیں گی۔</p><h2 id="_2-بنیادی-اصطلاحات-کی-جدول" tabindex="-1">2. بنیادی اصطلاحات کی جدول <a class="header-anchor" href="#_2-بنیادی-اصطلاحات-کی-جدول" aria-label="Permalink to &quot;2. بنیادی اصطلاحات کی جدول&quot;">​</a></h2><table tabindex="0"><thead><tr><th>نمبر</th><th>اصطلاح</th><th>تعریف اور وضاحت</th></tr></thead><tbody><tr><td>1</td><td>اینکر</td><td>قانون کے نیٹ ورک میں مستحکم نوڈ، جو جہت کے قوانین کی استحکام کو برقرار رکھنے، بین الجہتی کنکشن کو حقیقت میں لانے اور وقت کی بازیافت کے لیے کوآرڈینیٹ کا معیار ہے۔ اینکر بنیادی طور پر کسی مخصوص مقامی جگہ پر کائنات کے بنیادی قوانین کا اعلی کثافت گاڑھا ہونا ہے، جس میں خود کو برقرار رکھنے اور انشانکن کی صلاحیت موجود ہے۔</td></tr><tr><td>2</td><td>اینکر سمبیوسس تہذیب</td><td>ایک تہذیب کی شکل جس میں اینکر طریقہ کار کو تکنیکی بنیاد کے طور پر اور سمبیوسس ارتقاء کو بنیادی تصور کے طور پر لیا گیا ہے۔ یہ لوٹ مار کے حصول کے نظام کی مخالفت کرتا ہے، اور قسمت اور ارتقاء کے انتخاب کا حق تمام مخلوقات کو واپس کرنے کی وکالت کرتا ہے، اور زیادہ کام زیادہ فائدہ، خود پیدا ہونا اور خود بڑھنا، سب کے لیے راستہ، تمام نسلوں کی مشترکہ ترقی کو حقیقت میں لاتا ہے۔</td></tr><tr><td>3</td><td>ہینگیوانژو</td><td>&quot;وانلنگ ہینگماؤ بینیوان ژو&quot; کا مخفف، جو وہ پوری کائنات ہے جس میں اینکر سمبیوسس تہذیب رہتی ہے اور حکومت کرتی ہے۔ یہ مادی جہت، توانائی کی تہہ، شعور کا دائرہ اور قانون کے نیٹ ورک چار تہوں پر مشتمل ایک مرکب وجود ہے۔</td></tr><tr><td>4</td><td>وانلنگ ہینگماؤ بینیوان ژو</td><td>ہینگیوانژو کا مکمل نام۔ &quot;وانلنگ&quot; سے مراد وہ تمام زندگی کی شکلیں ہیں جن میں ادراک اور ارتقاء کی صلاحیت ہے، &quot;ہینگماؤ&quot; سے مراد وہ اینکر طریقہ کار ہے جو کائنات کے توازن کو برقرار رکھتا ہے، &quot;بینیوان ژو&quot; اس بنیادی خاصیت پر زور دیتا ہے جس میں بنیادی قوانین کو بنیاد کے طور پر اور سمبیوسس ارتقاء کو سمت کے طور پر لیا گیا ہے۔</td></tr><tr><td>5</td><td>سمبیوسس</td><td>اینکر سمبیوسس تہذیب کے بنیادی تصورات میں سے ایک، جس سے مراد مختلف جاندار افراد، نسلوں اور تہذیبوں کے درمیان باہر فائدہ مند تعاون کے ذریعے مشترکہ ارتقاء کو حقیقت میں لانا ہے، نہ کہ دوسروں کی قیمت پر لوٹ مار کے ارتقاء۔</td></tr><tr><td>6</td><td>لوٹ مار کا حصول کا نظام</td><td>ایک حصول کا طریقہ جو کمزوروں کی توانائی، قسمت اور یہاں تک کہ اصل کو کھا کر اپنا ارتقاء حقیقت میں لاتا ہے۔ یہ وہ نظام کی قسم ہے جس کی اینکر سمبیوسس تہذیب سختی سے مخالفت کرتی ہے، اور اسے کائنات کے اینٹروپی میں تیز اضافے اور تہذیبوں کے وقفے وقفے سے ٹوٹنے کی جڑ کے طور پر سمجھا جاتا ہے۔</td></tr><tr><td>7</td><td>تین سو سیٹ اصل حصول کا نظام</td><td>کائنات کے بنیادی قوانین سے براہ راست نکھرے ہوئے اور اینکر کے ذریعے تصدیق شدہ مستند حصول کے راستے، کل تین سو سیٹ، جو اصل تخمینہ قسم، زندگی چکر قسم، مقامی قانون قسم، شعور کی بلندی قسم، سمبیوسس نیٹ ورک قسم، اطلاقی انجینئرنگ قسم چھ اقسام میں تقسیم ہیں، ہر قسم میں پچاس سیٹ۔</td></tr><tr><td>8</td><td>اصل تین بنیادیں</td><td>تین سو سیٹ نظام میں پہلے تین بنیادی سیٹ — تخمینہ تکراری نظام (پہلا سیٹ)، زندگی چکر نظام (دوسرا سیٹ)، مقامی قانون کنٹرول نظام (تیسرا سیٹ)، جو دوسرے تمام نظاموں کی حصول کی بنیاد ہیں۔</td></tr><tr><td>9</td><td>تخمینہ تکراری نظام</td><td>پہلا سیٹ اصل حصول کا نظام، جس کی بنیادی خصوصیت سو گنا حصول تخمینہ اضافہ ہے، اور یہ ضرب پھل کی تکنیکی اطلاق کے ذریعے تخمینہ کی صلاحیت کو سو گنا بڑھاتا ہے، اور تخمینہ، تصدیق، تکرار کے ذریعے حصول کے راستے کو بہتر بنانے پر زور دیتا ہے۔</td></tr><tr><td>10</td><td>زندگی چکر نظام</td><td>دوسرا سیٹ اصل حصول کا نظام، جس کی بنیاد زندگی کی توانائی کے اچھے چکر پر ہے، اور اس پر زور دیا جاتا ہے کہ حصول کار کے اپنے اور ماحول کے درمیان توانائی کا تبادلہ چکر کے لحاظ سے ہونا چاہیے، نہ کہ لوٹ مار کے لحاظ سے۔</td></tr><tr><td>11</td><td>مقامی قانون کنٹرول نظام</td><td>تیسرا سیٹ اصل حصول کا نظام، جس کی بنیاد مقامی قوانین کی سمجھ اور کنٹرول پر ہے، اور یہ بین الجہتی تعامل، الگ تھلگ جگہ کی تعمیر، کاپی آئینہ ٹیکنالوجی جیسے اہم اطلاقات کی حصول کی بنیاد ہے۔</td></tr><tr><td>12</td><td>ضرب پھل</td><td>ون پیس کی دنیا سے آیا ضرب پھل، جو ہینگیوانژو میں تکنیکی طور پر اطلاق کیا جاتا ہے، اور یہ حصول کار کی تخمینہ کی صلاحیت کو سو گنا بڑھانے میں صلاحیت رکھتا ہے، اور یہ تخمینہ تکراری نظام کا بنیادی معاون آلہ ہے۔ ابتدائی بفوں میں سے ایک۔</td></tr><tr><td>13</td><td>مشترکہ پیداوار معاہدہ طریقہ کار</td><td>اینکر سمبیوسس تہذیب کے وسائل کی تقسیم کا طریقہ کار، جو کائنات کے حصول وسائل کو &quot;معاہدہ&quot; کے ذریعے افراد یا گروہوں کو تقسیم کرتا ہے، اور معاہدہ کار مشقت اور شراکت کے ذریعے وسائل کے استعمال کا حاصل کرتا ہے، اور زیادہ کام زیادہ فائدہ کو حقیقت میں لاتا ہے۔</td></tr><tr><td>14</td><td>20% ایکٹیویشن حکمت عملی</td><td>اینکر سمبیوسس تہذیب کا مرحلہ وار حکمت عملی کا مقصد، ابتدائی مرحلے میں پوری کائنات کے 20% مخلوقات کو جہت کے سب سے اعلیٰ طاقتور افراد کے طور پر ایکٹیو کرنا، اور انہیں ہڈی کے طور پر بقیہ 80% مخلوقات کی مشترکہ ارتقاء کو آگے بڑھانا۔</td></tr><tr><td>15</td><td>جہت کا سب سے اعلیٰ طاقتور فرد</td><td>وہ طاقتور فرد جس کی حصول انتہائی اعلیٰ سطح پر پہنچ گئی ہے اور وہ اکیلے ایک جہت کے قوانین کی استحکام کو برقرار رکھنے میں صلاحیت رکھتا ہے۔ یہ 20% ایکٹیویشن حکمت عملی کا ہدف تربیت کا موضوع ہے، اور یہ اینکر نیٹ ورک کی اہم دیکھ بھال کی طاقت بھی ہے۔</td></tr><tr><td>16</td><td>قانون کا نیٹ ورک</td><td>ہینگیوانژو کے ڈھانچے کی چوتھی تہہ، جو کائنات کے بنیادی قوانین کے چلنے والی نچلی تہہ اور اینکر کی جڑ کی تہہ ہے۔ قانون کا نیٹ ورک پوری کائنات میں پھیلا ہوا ہے، اور یہ تمام قانونی آپریشنز (بشمول مقامی کنٹرول، وقت کی بازیافت، توانائی کی تبدیلی) کی تکنیکی بنیاد ہے۔</td></tr><tr><td>17</td><td>جہت</td><td>ایک وجود کا علاقہ جو نسبتاً مستحکم قوانین کے ایک مجموعے سے متعین ہوتا ہے، جس میں آزاد مقامی وقتی تسلسل ہوتا ہے۔ ہر جہت کے منفرد طبعی مستقل، توانائی کی کثافت، وقت کے بہاؤ کی رفتار اور شعور کی سرگرمی ہوتی ہے۔</td></tr><tr><td>18</td><td>قانون کی رکاوٹ</td><td>ملحقہ جہتوں کو الگ کرنے والی قانونی رکاوٹ، جس کی طاقت ملحقہ جہتوں کے درمیان قانونی پیرامیٹرز کے فرق کی ڈگری پر منحصر ہے۔ جہت کی عبور کے لیے قانون کی رکاوٹ پر قابو پانا ضروری ہے۔</td></tr><tr><td>19</td><td>قانون کے فنگر پرنٹ</td><td>ہر جہت کے بنیادی قانونی پیرامیٹرز کے ہیش آپریشن کے ذریعے تیار کردہ منفرد شناخت کار، جس کی لمبائی 128 بٹ ہے، اور یہ جہت کے کوآرڈینیٹ سسٹم کے بنیادی پیرامیٹرز میں سے ایک ہے۔</td></tr><tr><td>20</td><td>پہلے مشاہدہ پھر محدود مداخلت</td><td>وقت کی بازیافت اور بین الجہتی آثار قدیمہ کا بنیادی آپریشن اصول، جس کا تقاضا ہے کہ کسی بھی بازیافت یا آثار قدیمہ کو پہلے خالص مشاہدے کے مرحلے کو مکمل کرنا چاہیے، اور صرف اس بات کی تصدیق کے بعد کہ کوئی بڑا خطرہ نہیں ہے، محدود مداخلت کی جا سکتی ہے۔</td></tr><tr><td>21</td><td>کاپی آئینہ</td><td>مقامی قوانین پر مبنی اعلی درستگی کاپی ڈیوائس، جو اصل چیز سے رابطہ کیے بغیر ہدف کے علاقے کی 1:1 مکمل کاپی کرنے میں صلاحیت رکھتا ہے، اور یہ دور دراز آثار قدیمہ کی اسکیم کا بنیادی سامان ہے۔</td></tr><tr><td>22</td><td>الگ تھلگ جگہ</td><td>مقامی قانون کنٹرول ٹیکنالوجی کے ذریعے بنائی گئی آزاد قانونی علاقہ، جو آثار قدیمہ کی کاپی کو لے جانے اور آثار قدیمہ کے کارکنوں کے کام کی جگہ کے طور پر استعمال ہوتی ہے، اور یہ بیرونی کائنات سے قانون کی رکاوٹ سے مکمل طور پر الگ ہے۔</td></tr><tr><td>23</td><td>صرف علم کی واپسی</td><td>آثار قدیمہ پروٹوکول کا بنیادی اصول، جس سے مراد یہ ہے کہ آثار قدیمہ کے عمل میں ہدف چیز سے جو کچھ حاصل کیا جاتا ہے وہ صرف تجریدی علم اور معلومات ہو سکتی ہے، اور کوئی بھی مادہ، توانائی یا جاندار واپس نہیں کیا جا سکتا۔</td></tr><tr><td>24</td><td>معلومات کی پاکیزگی</td><td>اصل معلومات میں لے جانے والی ماخذ جہت کے قانونی نشانات کو مکمل طور پر ہٹا کر، صرف خالص معنوی مواد کو برقرار رکھنے کی تکنیکی عمل، جو واپس کیے جانے والے علم کی حفاظت کو یقینی بنانے کا کلیدی حصہ ہے۔</td></tr><tr><td>25</td><td>وقت کا پیراڈوکس</td><td>وقت کی بازیافت کے آپریشن میں مداخلت کے رویے کی وجہ سے وجہ اور نتیجہ کی منطق میں خود تضادی واقعہ کا واقع ہونا، جس میں دادا کے قتل کا پیراڈوکس، معلومات کا پیراڈوکس، وجودیت کا پیراڈوکس اور واقعہ کا پیراڈوکس چار بڑی اقسام شامل ہیں۔</td></tr><tr><td>26</td><td>وجہ اور نتیجہ کی زنجیر</td><td>واقعات کے درمیان پہلے وجہ اور بعد میں نتیجہ کی مسلسل لکیری ڈھانچہ، جو وقت کے قوانین کا بنیادی تصور ہے۔ وقت کی بازیافت کے آپریشن کا بنیادی خطرہ وجہ اور نتیجہ کی زنجیر میں خلل ڈالنا ہے۔</td></tr><tr><td>27</td><td>سمبیوسس آئین</td><td>اینکر سمبیوسس تہذیب کا بنیادی قانون، جس میں سب سے زیادہ قانونی طاقت ہے، اور اس نے لوٹ مار مخالف، سمبیوسس کی حمایت کرنے والی تہذیب کی بنیاد اور آئین کے سات بنیادی اصول قائم کیے ہیں۔</td></tr><tr><td>28</td><td>تمام نسلوں کی برابری</td><td>سمبیوسس آئین کے سات بنیادی اصولوں میں سے ایک، جس سے مراد یہ ہے کہ تمام زندگی کی شکلیں نسل، حصول کی سطح، یا اصل سے قطع نظر، قانون کے سامنے برابر ہیں۔</td></tr><tr><td>29</td><td>عجیب زندگی</td><td>وہ زندگی کی شکل جو روایتی زندگی کی تعریف کے مطابق نہیں ہے اور خاص وجود کی شکل رکھتی ہے، جسے تین قسم کے معیاری علاج کے عمل کے مطابق شناخت اور انتظام کرنا ضروری ہے۔</td></tr><tr><td>30</td><td>عجیب توانائی</td><td>وہ توانائی کی شکل جو روایتی توانائی کی درجہ بندی کے مطابق نہیں ہے اور خاص صفات اور رویے کے نمونے رکھتی ہے، جسے تین قسم کے معیاری علاج کے عمل کے مطابق درجہ بندی اور کنٹرول کرنا ضروری ہے۔</td></tr><tr><td>31</td><td>تاریکی متبادل جسم</td><td>ایک خاص زندگی کی شکل، جس میں دو روحوں کے باہمی وجود کے اخلاقی مسائل شامل ہیں، جسے دو روحوں کے اخلاقی رہنما اصولوں اور چار قسم کے شاخوں کے علاج کے قواعد کے مطابق انتظام کرنا ضروری ہے۔</td></tr><tr><td>32</td><td>دو روحوں کی اخلاقیات</td><td>تاریکی متبادل جسم میں دو روحوں کے باہمی وجود کی حالت کے لیے اخلاقی رہنما اصول، جس کی بنیاد دو روحوں کے اپنے اپنے حقوق کا احترام کرنا ہے، اور جبری امتزاج یا کسی ایک فریق کو ختم کرنا ممنوع ہے۔</td></tr><tr><td>33</td><td>پانچ قسم کی سمبیوسس تہذیب کی درجہ بندی</td><td>حقیقی دنیا کی تہذیبوں کی خصوصیات کی بنیاد پر تقسیم کی گئی پانچ قسم کی سمبیوسس معاشرتی اقسام: مشرقی ایشیا کی گھنے قسم، شمالی یورپ کی فلاح و بہبود کی قسم، شمالی امریکہ کی کثیر الثانی قسم، براعظم یورپ کی سماجی قسم، ترقی پذیر پیچھا کرنے والی قسم۔</td></tr><tr><td>34</td><td>چار مراحل کی بلندی کا راستہ</td><td>ہینگیوانژو کائنات کی مجموعی بلندی کے چار مراحل کا راستہ: حقیقت کی بنیاد تیار کرنا → ٹیکنالوجی سے بااختیار بنانا → شعور کا ارتقاء → بین ستاروں کا سمبیوسس۔</td></tr><tr><td>35</td><td>حقیقت کو بنیاد کے طور پر</td><td>اینکر سمبیوسس تہذیب کے بنیادی موقفوں میں سے ایک، جس سے مراد یہ ہے کہ حقیقی دنیا ہی واحد حقیقی دنیا ہے، ناول کی دنیا جھوٹا فکری تجربہ ہے، خیالی چیزیں حقیقت سے مکمل نہیں ہوتیں، اور جو چیز حقیقت میں نہیں ہے اسے قوانین کی بنیاد پر اپ گریڈ کر کے تخلیق کیا جاتا ہے۔</td></tr><tr><td>36</td><td>سمبیوسس کی ڈگری</td><td>کسی تہذیب یا فرد کی سمبیوسس نیٹ ورک کے ساتھ انضمام کی ڈگری کا اندازہ کرنے والا مقداری اشارے، جس میں وسائل کے اشتراک کی ڈگری، تعاون کی تعدد، پرہیزگاری کے رویے کا تناسب جیسے متعدد جہتیں شامل ہیں۔</td></tr><tr><td>37</td><td>اینکر کونسل</td><td>اینکر سمبیوسس تہذیب کا اعلیٰ ترین طاقت کا ادارہ، جو تمام نسلوں کے نمائندوں پر مشتمل تناسب کے لحاظ سے تشکیل پاتا ہے، اور قانون سازی کی طاقت اور اہم معاملات کے فیصلے کی طاقت کا استعمال کرتا ہے۔</td></tr><tr><td>38</td><td>سمبیوسس ایگزیکٹو کمیٹی</td><td>اینکر سمبیوسس تہذیب کا اعلیٰ ترین انتظامی ادارہ، جو آئین اور قوانین کے نفاذ، روزمرہ کی حکمرانی کے لیے ذمہ دار ہے۔</td></tr><tr><td>39</td><td>سمبیوسس عدالت</td><td>اینکر سمبیوسس تہذیب کا اعلیٰ ترین عدالتی ادارہ، جو آزادانہ طور پر عدلیہ کی طاقت کا استعمال کرتا ہے، اور غیر آئینگی جانچ اور اہم مقدمات کی سماعت کے لیے ذمہ دار ہے۔</td></tr><tr><td>40</td><td>جہت انتظامی بیورو</td><td>اینکر کونسل کے ماتحت ایک خاص ادارہ، جو جہت کے کوآرڈینیٹ کل بینک کی دیکھ بھال، عبور کی اجازت کی منظوری، بین الجہتی آثار قدیمہ کی انتظامیہ اور دیگر معاملات کے لیے ذمہ دار ہے۔</td></tr></tbody></table><h2 id="_3-اصطلاحات-کے-استعمال-کے-اصول" tabindex="-1">3. اصطلاحات کے استعمال کے اصول <a class="header-anchor" href="#_3-اصطلاحات-کے-استعمال-کے-اصول" aria-label="Permalink to &quot;3. اصطلاحات کے استعمال کے اصول&quot;">​</a></h2><ol><li>اس لغت میں جمع کی گئی اصطلاحات معیاری اصطلاحات ہیں، اور تمام دستاویزات کو اس لغت میں معیاری اظہار کو ترجیح دینی چاہیے۔</li><li>ایک ہی تصور کو مختلف دستاویزات میں ایک ہی اصطلاح کا استعمال کرنا چاہیے، اور اپنی مرضی سے مترادفات کو تبدیل نہیں کرنا چاہیے۔</li><li>نئے ترتیب میں پیدا ہونے والی نئی اصطلاحات کو بروقت اصطلاحات کی کمیٹی میں جمع کروا کر جائزہ کے لیے بھیجنا چاہیے، اور جائزہ پاس ہونے کے بعد اس لغت میں شامل کیا جائے گا۔</li><li>اگر کسی اصطلاح کی تعریف میں ترمیم کی جاتی ہے، تو اس لغت کے تازہ ترین نسخے کو معیار کے طور پر لیا جائے گا، اور ساتھ ہی ترمیم کے مواد کو دستاویز کے نسخے کی وضاحت میں ریکارڈ کرنا ضروری ہے۔</li><li>اصطلاح کا حوالہ دیتے وقت، پہلی بار پورا نام استعمال کیا جا سکتا ہے، بعد میں مخفف استعمال کیا جا سکتا ہے، لیکن یہ یقینی بنانا ضروری ہے کہ سیاق و سباق میں معنی واضح ہوں۔</li></ol><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>اصطلاحات کا لغت پورے ترتیب کے نظام کی لسانی بنیاد ہے۔ متحد اصطلاحات کا نظام سو دستاویزات کے درمیان تصورات کی مستقل مزاجی کو یقینی بناتا ہے، اور قارئین کو مختلف ماڈیولز کے درمیان بغیر کسی سمجھوتے کے بغیر آسانی سے منتقل ہونے کے قابل بناتا ہے۔ ترتیب کے نظام کی مسلسل افزائش اور بہتری کے ساتھ ساتھ، یہ لغت مسلسل اپ ڈیٹ ہوتی رہے گی، اور ہمیشہ تمام دستاویزات کے لیے اصطلاحات کا مستند ذریعہ بنی رہے گی۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>00-ہینگیوانژو کائنات کا عمومی جائزہ</li><li>02-اینکر اصل کی تعریف اور نوعیت</li><li>99-دستاویز کے نسخے اور دیکھ بھال کی وضاحت</li></ul>',12)])])}const b=d(l,[["render",o]]);export{c as __pageData,b as default};
